#define GROOVE_DICE_TEST
#include "../src/GrooveDice.cpp"
#include <cassert>
#include <set>
#include <iostream>
struct Host{GrooveDice p;float data[16][128]{},*out[16];Host(){for(int i=0;i<16;++i)out[i]=data[i];p.prepare(44100,128);p.reset();}double block(){for(auto&c:data)std::fill(c,c+128,0);mpc::ProcessContext c;c.outputs=out;c.numOutputs=16;c.numFrames=128;c.sampleRate=44100;p.process(c);double e=0;for(auto&a:data)for(float v:a){assert(std::isfinite(v));e+=v*v;}return e;}void pulse(int key){p.set(key,p.getBool(key)?0:1);block();}void ready(){for(int n=0;n<3000;++n){block();bool done=true;for(int r=0;r<8;++r)if(p.getInt(kLibrarySample0+r)!=p.library.active[r].load())done=false;if(done)return;std::this_thread::sleep_for(std::chrono::milliseconds(1));}assert(false);}};
int main(){Host h;auto&p=h.p;auto&l=p.library;assert(kActionInfo==291&&kMixKick==342&&kParamCount==533);std::set<std::string>names;
 for(int k=3;k<5;++k)for(int id:l.categories[k]){const auto&name=l.entries[id].name;assert(name.find("MPC")==std::string::npos&&name.find("SP1200")==std::string::npos&&name.find("AppleJacks")==std::string::npos);assert(names.insert(name).second);assert(!l.midi[id].notes.empty());}assert(names.size()==95);std::cout<<"PASS 95 unique MIDI entries indexed and parsed\n";
 p.selectFactoryProgram(4);h.block();std::array<int,4> main{};for(int r=0;r<4;++r)main[r]=p.getInt(kLibrarySample0+r);p.set(kPadNote7,70);p.set(kRoute7,2);p.set(kRoom,17);p.notes[0][0].write({240,7,99,100,80});int oldFill=p.countNotes(0);
 for(int n=1;n<=244;++n){p.set(kSoundPerc,n);h.block();assert(p.getInt(kSoundPerc)==n);const auto&c=l.soundPools[3][n-1];assert(c.name.find("Perc Set")!=std::string::npos);for(int j=0;j<4;++j){int role=j==0?7:j+3;assert(c.sounds[j]>0&&p.getInt(kLibrarySample0+role)==c.sounds[j]);assert(std::abs(p.get(kLevel0+role*9)-c.parts[j][0])<.0001f);}for(int r=0;r<4;++r)assert(p.getInt(kLibrarySample0+r)==main[r]);assert(p.getInt(kPadNote7)==70&&p.getInt(kRoute7)==2&&std::abs(p.get(kRoom)-17)<.0001f&&p.countNotes(0)==oldFill);}
 std::cout<<"PASS244 four-instrument Perc sets apply together; Kick/Snare/Hats, pad routing, FX and fill preserved\n";
 h.ready();for(int r=4;r<8;++r){p.reset();h.pulse(kPad0+r*9);double energy=0;for(int n=0;n<100;++n)energy+=h.block();assert(energy>1e-9);}std::cout<<"PASS Clap/Tom/Cymbal/Perc four distinct actual WAV voices audible\n";
 p.set(kKitLock,0);p.set(kScope,0);p.set(kKitDiceMode,1);p.set(kRandomAmt,100);for(int n=0;n<100;++n){h.pulse(kRoll);bool found=false;for(const auto&c:l.soundPools[3]){bool match=true;for(int j=0;j<4;++j)if(p.getInt(kLibrarySample0+(j==0?7:j+3))!=c.sounds[j])match=false;if(match)found=true;}assert(found);}auto state=p.internalSaveState();assert(p.internalLoadState(state.data(),state.size()));p.reset();for(int n=0;n<180;++n)h.block();assert(p.internalSaveState()==state);std::cout<<"PASS100 Mix Parts rolls keep complete Perc ensembles; byte-identical state roundtrip\n";
 for(int key:{kSoundPick0,kSoundPick7,kLibraryPick0,kLibraryPick7,kSoundNext,kKitPagePrev,kPatternPrev,kGridTap,kFactoryReload}){p.lastAction.store(key);auto text=p.displayText(kActionInfo);assert(text.find("Pick")==std::string::npos&&text.find("Factory")==std::string::npos&&text.find("Grid")==std::string::npos&&text.size()<=31);}std::cout<<"PASS action acknowledgements contain user-facing labels, no internal command IDs\n";
 unsigned before=p.actionCount.load();for(int n=0;n<4;++n){h.pulse(kRoll);assert(p.actionCount.load()==before+n+1);assert(p.displayText(kActionInfo).find("Roll Dice")!=std::string::npos);}std::cout<<"PASS repeated button commands each advance visible action acknowledgement once\n";
}
